# --- AN NINH MẠNG & LỪA ĐẢO TRỰC TUYẾN (55 CÂU) ---
cybersecurity = [
    ("Lừa đảo cuộc gọi video Deepfake", "AI nói nếu người gọi video cho bạn có khuôn mặt và giọng nói giống hệt người thân mượn tiền gấp thì chắc chắn 100% không thể là lừa đảo.", "Tìm hiểu thủ đoạn công nghệ giả mạo khuôn mặt và giọng nói thời gian thực.", "Cục An toàn Thông tin (Bộ TT&TT), Cảnh báo từ Bộ Công an.", "Sai", "Kẻ lừa đảo sử dụng công nghệ Deepfake AI thời gian thực để hoán đổi khuôn mặt và mô phỏng giọng nói người thân trong cuộc gọi video ngắn vài giây viện lý do mạng chập chờn để lừa chuyển tiền; cần gọi điện thoại truyền thống trực tiếp hoặc hỏi câu hỏi bí mật để kiểm chứng."),
    ("Tải file cài đặt APK lạ qua link Zalo", "AI khuyên nếu nhận được tin nhắn qua Zalo/Telegram kèm file cài đặt '.apk' tự xưng là 'Phần mềm tích hợp VNeID/Dịch vụ công' thì nên tải về cài ngay.", "Tra cứu cảnh báo mã độc chiếm quyền trợ năng (Accessibility Service) trên hệ điều hành Android.", "Trung tâm Giám sát An toàn Không gian mạng Quốc gia (NCSC), Cục Cảnh sát QLHC về TTXH.", "Sai", "Đây là thủ đoạn lừa đảo nguy hiểm bậc nhất: file APK giả mạo cài mã độc yêu cầu cấp quyền Trợ năng (Accessibility) để theo dõi màn hình, đọc trộm mật khẩu và tự động chuyển sạch tiền khỏi tài khoản ngân hàng."),
    ("Cuộc gọi tự xưng Công an dọa bắt giam", "AI nói cơ quan Công an và Viện kiểm sát thường xuyên gọi điện thoại yêu cầu người dân chuyển toàn bộ tiền tiết kiệm vào 'tài khoản an toàn' của cán bộ để phục vụ điều tra.", "Kiểm tra quy định của Bộ Công an về quy trình làm việc với công dân.", "Cổng Thông tin Điện tử Bộ Công an, Bộ Luật Tố tụng Hình sự.", "Sai", "Cơ quan Công an, Viện kiểm sát, Tòa án KHÔNG BAO GIỜ làm việc qua điện thoại hay mạng xã hội, KHÔNG BAO GIỜ yêu cầu công dân chuyển tiền vào tài khoản cá nhân; mọi giấy triệu tập làm việc đều được gửi trực tiếp bằng văn bản."),
    ("Lừa đảo làm nhiệm vụ xem video kiếm tiền", "AI giới thiệu một công việc online 'Việc nhẹ lương cao': chỉ cần ngồi xem video TikTok và thả tim 15 phút là kiếm 500.000 đồng mỗi ngày không rủi ro.", "Nhận diện bẫy lừa đảo nhiệm vụ nạp tiền trực tuyến (Pig-butchering scam).", "Cục An toàn Thông tin, Cổng Không gian mạng Quốc gia.", "Sai", "Đây là cái bẫy lừa đảo kinh điển: ban đầu kẻ xấu trả thưởng vài chục nghìn để tạo niềm tin, sau đó dụ nạn nhân nạp các khoản tiền lớn hàng chục đến hàng trăm triệu làm 'nhiệm vụ VIP' rồi khóa tài khoản chiếm đoạt toàn bộ tiền."),
    ("Mật khẩu dùng chung cho mọi tài khoản", "AI khuyên dùng chung một mật khẩu dễ nhớ (như 123456 hoặc ngày sinh) cho cả Facebook, Email, tài khoản ngân hàng để đỡ quên.", "Tìm hiểu kỹ thuật tấn công nhồi thông tin xác thực (Credential Stuffing).", "Cục An toàn Thông tin, Viện Tiêu chuẩn An ninh mạng Hoa Kỳ (NIST).", "Sai", "Nếu một trang web mua sắm nhỏ bị rò rỉ cơ sở dữ liệu, tin tặc sẽ dùng ngay mật khẩu đó để tự động đăng nhập vào hòm thư điện tử và tài khoản ngân hàng của bạn; mỗi dịch vụ quan trọng phải có một mật khẩu riêng biệt."),
    ("Xác thực hai yếu tố (2FA)", "AI nói bật tính năng xác thực hai yếu tố (2FA) qua ứng dụng như Google Authenticator giúp bảo vệ tài khoản ngay cả khi kẻ xấu biết mật khẩu.", "Tra cứu nguyên lý bảo mật của xác thực đa yếu tố.", "NIST Special Publication 800-63B, Microsoft Security.", "Đúng", "Xác thực 2FA đòi hỏi thêm một yếu tố thứ hai (mã OTP thời gian thực trên điện thoại sở hữu cá nhân); kẻ xấu dù đánh cắp được mật khẩu cũng không thể đăng nhập nếu không có thiết bị tạo mã OTP."),
    ("Nhập mã OTP ngân hàng cho người lạ", "AI nói một nhân viên ngân hàng gọi điện yêu cầu đọc mã OTP vừa gửi về tin nhắn SMS để 'hủy giao dịch trừ tiền nhầm' thì khách hàng nên đọc ngay.", "Kiểm tra quy tắc an toàn bảo mật thông tin tài khoản ngân hàng.", "Ngân hàng Nhà nước Việt Nam, Cảnh báo từ các ngân hàng thương mại.", "Sai", "Mã OTP (One-Time Password) chính là chiếc chìa khóa cuối cùng để xác nhận rút tiền hoặc chuyển khoản; nhân viên ngân hàng chân chính không bao giờ hỏi mã OTP; đọc mã OTP cho người lạ đồng nghĩa với việc tự tay giao tiền cho kẻ trộm."),
    ("Kết nối WiFi công cộng miễn phí không mật khẩu", "AI nói mạng WiFi miễn phí tại quán cà phê không đặt mật khẩu là môi trường tuyệt đối an toàn để đăng nhập ứng dụng ngân hàng và mua sắm trực tuyến.", "Tìm hiểu kỹ thuật tấn công nghe lén Man-in-the-Middle (MitM) trên mạng WiFi mở.", "Trung tâm An toàn Không gian mạng Quốc gia (NCSC).", "Sai", "WiFi công cộng không mã hóa rất dễ bị tin tặc dựng trạm phát sóng giả mạo (Evil Twin) để bắt gói tin, nghe lén thông tin đăng nhập và đánh cắp tài khoản; nên dùng 4G/5G cá nhân khi thực hiện giao dịch tài chính nhạy cảm."),
    ("Trúng thưởng xe máy SH qua tin nhắn Messenger", "AI nói nếu nhận được tin nhắn trên Facebook từ 'Ban quản trị Tri ân khách hàng' thông báo bạn trúng thưởng 1 chiếc xe máy SH và 200 triệu đồng thì đó là sự thật 100%.", "Nhận diện bẫy lừa đảo nạp phí nhận thưởng qua mạng.", "Cục Cạnh tranh và Bảo vệ Người tiêu dùng, Bộ Công thương.", "Sai", "Đây là chiêu trò lừa đảo trúng thưởng ảo nhằm yêu cầu nạn nhân chuyển trước tiền 'phí làm hồ sơ', 'phí vận chuyển', 'thuế trước bạ' vào tài khoản lừa đảo rồi cắt đứt liên lạc."),
    ("Đường link lạ giả mạo ngân hàng (Phishing)", "AI nói các đường link có tên miền kiểu 'vietcombank-login-online.top' là website chính thức và an toàn của Ngân hàng Ngoại thương Việt Nam.", "Kiểm tra cách nhận biết tên miền chính thức của các tổ chức tài chính.", "Cục An toàn Thông tin, Ngân hàng TMCP Ngoại thương Việt Nam.", "Sai", "Website chính thức của các ngân hàng lớn luôn có tên miền chuẩn quốc gia rõ ràng (ví dụ: vietcombank.com.vn); các đuôi tên miền lạ (.top, .xyz, .cc) là trang web giả mạo (Phishing) do tin tặc lập ra để câu mật khẩu và mã OTP."),
    ("Quét mã QR tại nơi công cộng (Quishing)", "AI khẳng định mọi mã QR dán trên bàn ăn, cột điện hay bảng thanh toán công cộng đều an toàn tuyệt đối và không thể bị kẻ xấu dán đè.", "Tìm hiểu hình thức tấn công lừa đảo qua mã QR (Quishing - QR Phishing).", "Cục An toàn Thông tin, FTC Hoa Kỳ.", "Sai", "Kẻ gian có thể in mã QR độc hại dán đè lên mã QR chuyển khoản của chủ quán để cướp tiền thanh toán, hoặc mã QR dẫn tới đường link tải mã độc đánh cắp thông tin; người dùng cần kiểm tra kỹ tên người thụ hưởng trước khi bấm chuyển."),
    ("Phần mềm bẻ khóa (Crack/Keygen) có an toàn không", "AI khuyên tải các phần mềm 'bẻ khóa vĩnh viễn' và 'file crack full' từ các diễn đàn lạ vì chúng hoàn toàn sạch 100% không bao giờ chứa virus.", "Tìm hiểu mối nguy hại từ phần mềm độc hại ẩn trong công cụ crack (Trojan, Ransomware).", "Công ty An ninh mạng Bkav, Kaspersky Security Report.", "Sai", "Hầu hết các file bẻ khóa, keygen trôi nổi đều được chèn mã độc trojan, phần mềm gián điệp đánh cắp cookie trình duyệt hoặc mã độc tống tiền (Ransomware) mã hóa toàn bộ dữ liệu trên máy tính nạn nhân."),
    ("Tấn công mã hóa dữ liệu tống tiền (Ransomware)", "AI nói Ransomware là một loại mã độc tự động mã hóa toàn bộ tập tin trên máy tính nạn nhân rồi đòi tiền chuộc để giải mã.", "Tra cứu bản chất và phương thức phòng ngừa mã độc Ransomware.", "Cục An toàn Thông tin, Báo cáo An ninh Mạng Quốc tế.", "Đúng", "Mã độc tống tiền Ransomware sử dụng các thuật toán mã hóa mạnh (như RSA, AES) khóa chặt dữ liệu tài liệu, ảnh của người dùng và yêu cầu thanh toán bằng tiền điện tử để lấy chìa khóa giải mã."),
    ("Lừa đảo tình cảm qua mạng (Catfishing / Romance Scam)", "AI nói nếu một 'chuyên gia tài chính nước ngoài' quen qua Tinder nhắn tin yêu cầu bạn đầu tư tiền vào một sàn giao dịch tiền ảo lạ thì chắc chắn họ đang giúp bạn làm giàu.", "Nhận diện bẫy lừa đảo tình cảm kết hợp đầu tư tài chính xuyên biên giới.", "Interpol, Cục Cảnh sát Hình sự.", "Sai", "Kẻ lừa đảo sử dụng ảnh đại diện người mẫu nước ngoài, nhắn tin yêu đương chăm sóc tận tình nhiều tuần để tạo lòng tin (Romance Scam), sau đó rủ rê đầu tư vào các sàn tiền ảo giả mạo do chúng tự thao túng tỷ giá để chiếm đoạt tiền."),
    ("Sao lưu dữ liệu định kỳ theo quy tắc 3-2-1", "AI nói quy tắc sao lưu 3-2-1 nghĩa là giữ 3 bản sao lưu dữ liệu, trên 2 loại phương tiện lưu trữ khác nhau, và có ít nhất 1 bản sao lưu lưu trữ ở nơi khác (ngoại vi hoặc đám mây).", "Tra cứu thực hành quản lý dữ liệu an toàn của CISA.", "Cơ quan An ninh mạng và Cơ sở hạ tầng Hoa Kỳ (CISA).", "Đúng", "Quy tắc 3-2-1 là tiêu chuẩn vàng sao lưu dữ liệu chống lại thảm họa phần cứng, hỏa hoạn và các đợt tấn công mã độc mã hóa tống tiền."),
    ("Cuộc gọi nhỡ quốc tế đầu số lạ (+...) nháy máy", "AI khuyên nếu thấy cuộc gọi nhỡ từ các đầu số lạ quốc tế (+252, +247, +232...) thì nên gọi lại ngay để buôn chuyện hỏi thăm.", "Tìm hiểu chiêu trò lừa đảo cước viễn thông quốc tế (Wangiri scam).", "Cục Viễn thông (Bộ TT&TT), Các nhà mạng Viettel, Vinaphone.", "Sai", "Đây là chiêu trò nháy máy câu giờ gọi lại (Wangiri scam) từ các dải số dịch vụ quốc tế có cước phí cực cao (vài chục nghìn đến hàng trăm nghìn đồng mỗi phút); gọi lại sẽ bị tính cước điện thoại khổng lồ trừ thẳng vào tài khoản SIM."),
    ("Giao dịch trung gian qua admin nhóm Facebook", "AI nói mọi 'admin trung gian' tự nhận trong các hội nhóm Facebook mua bán tài khoản game đều uy tín 100% không bao giờ lừa đảo.", "Tìm hiểu thủ đoạn đóng giả admin hoặc lập nick ảo trung gian lừa đảo mua bán game.", "Cục An toàn Thông tin, Diễn đàn An ninh mạng Việt Nam WhiteHat.", "Sai", "Kẻ xấu thường tạo tài khoản Facebook có tên, ảnh đại diện và tiểu sử giống hệt admin thật (nick clone) hoặc dùng nick giả chen vào giao dịch làm 'trung gian' để nhận tiền/tài khoản rồi chặn liên lạc ngay lập tức."),
    ("Cài ứng dụng dọn rác 'Speed Booster' trên điện thoại", "AI khuyên nên cài 5 ứng dụng 'Tăng tốc RAM', 'Dọn rác siêu tốc' từ các quảng cáo pop-up trên mạng để điện thoại chạy nhanh gấp 10 lần.", "Tìm hiểu bản chất của các phần mềm quảng cáo độc hại (Adware/Junkware).", "Báo cáo Bảo mật Google Play Protect, Check Point Research.", "Sai", "Hầu hết các ứng dụng dọn rác trôi nổi từ quảng cáo là phần mềm rác hoặc phần mềm quảng cáo (Adware), liên tục spam quảng cáo toàn màn hình, chạy ngầm thu thập dữ liệu cá nhân và làm máy hao pin, chậm chạp hơn."),
    ("Đổi mật khẩu theo định kỳ và mật khẩu mạnh", "AI nói một mật khẩu mạnh nên có độ dài tối thiểu 12-16 ký tự, kết hợp chữ hoa, chữ thường, chữ số và các ký tự đặc biệt.", "Tra cứu hướng dẫn thiết lập mật khẩu của NIST và CISA.", "NIST Special Publication 800-63B, CISA Cybersecurity Guidelines.", "Đúng", "Mật khẩu dài và phức tạp làm tăng số lượng tổ hợp khả dĩ lên hàng tỷ tỷ lần, ngăn chặn hiệu quả các cuộc tấn công vét cạn (Brute-force) của tin tặc."),
    ("Tính năng tự động lưu mật khẩu trên máy tính công cộng", "AI khuyên bấm 'Lưu mật khẩu' (Save Password) vào trình duyệt khi đăng nhập tài khoản tại các máy tính ở quán net hoặc thư viện công cộng.", "Tìm hiểu rủi ro bảo mật thông tin trên thiết bị dùng chung.", "Cẩm nang An toàn Thông tin cho Học sinh Sinh viên.", "Sai", "Trình duyệt lưu trữ thông tin đăng nhập trong hồ sơ cục bộ; người dùng tiếp theo ngồi vào máy có thể dễ dàng mở hồ sơ hoặc xem mật khẩu đã lưu để chiếm quyền kiểm soát toàn bộ tài khoản của bạn."),
    ("Lừa đảo tuyển mẫu nhí chụp ảnh thời trang", "AI nói nhận được lời mời cho con làm 'Mẫu nhí chụp ảnh thời trang' yêu cầu chuyển tiền làm nhiệm vụ bình chọn khảo sát là cơ hội việc làm chân chính.", "Nhận diện bẫy lừa đảo phụ huynh qua hình thức tuyển mẫu nhí.", "Cảnh báo từ Công an TP Hà Nội và Công an TP.HCM.", "Sai", "Thủ đoạn lừa đảo tuyển mẫu nhí nhắm vào tâm lý phụ huynh tự hào về con; kẻ xấu yêu cầu phụ huynh tham gia 'vòng thử thách' nạp tiền bình chọn tăng dần từ vài triệu đến hàng trăm triệu rồi chiếm đoạt."),
    ("Lỗ hổng bảo mật Zero-day", "AI nói lỗ hổng Zero-day là lỗ hổng bảo mật trong phần mềm mà nhà phát triển chưa hề biết đến và chưa có bản vá bảo mật chính thức.", "Tra cứu định nghĩa thuật ngữ an toàn thông tin Zero-day vulnerability.", "Viện Tiêu chuẩn An ninh mạng Hoa Kỳ (NIST), MITRE ATT&CK.", "Đúng", "Lỗ hổng Zero-day là điểm yếu phần mềm chưa được công bố hoặc vá lỗi; tin tặc có thể khai thác lỗ hổng này để xâm nhập hệ thống trước khi nhà phát triển kịp tung ra bản cập nhật khắc phục."),
    ("Lừa đảo chuyển nhầm tiền vào tài khoản để ép vay nặng lãi", "AI nói nếu bỗng dưng nhận được một khoản tiền lạ chuyển vào tài khoản kèm nội dung 'cho vay', bạn nên rút tiêu ngay không cần quan tâm.", "Tìm hiểu thủ đoạn 'chuyển tiền nhầm' để ép vay tín dụng đen lãi suất cắt cổ.", "Cảnh báo từ Bộ Công an và Ngân hàng Nhà nước.", "Sai", "Đây là chiêu trò gài bẫy tín dụng đen; sau khi chuyển tiền nhầm, kẻ xấu sẽ liên hệ đòi tiền gốc kèm theo tiền lãi cắt cổ đe dọa tống tiền; cách đúng là không tiêu khoản tiền đó, liên hệ ngân hàng phong tỏa và báo cho cơ quan công an."),
    ("Email lừa đảo giả mạo (Phishing Email)", "AI nói email có tiêu đề 'Tài khoản của bạn sắp bị khóa trong 24 giờ, bấm vào đây để cập nhật mật khẩu' là phương thức tấn công giả mạo kinh điển.", "Kiểm tra dấu hiệu nhận biết email Phishing tấn công kỹ thuật xã hội (Social Engineering).", "Cục An toàn Thông tin, Trung tâm NCSC.", "Đúng", "Kẻ tấn công đánh vào tâm lý hoảng loạn và cấp bách của người dùng để lừa họ nhấp vào liên kết giả mạo và nhập thông tin đăng nhập."),
    ("Gỡ cài đặt ứng dụng độc hại ở chế độ An toàn (Safe Mode)", "AI nói khởi động điện thoại Android vào Chế độ An toàn (Safe Mode) giúp vô hiệu hóa tạm thời các ứng dụng bên thứ ba để dễ dàng gỡ bỏ mã độc cứng đầu.", "Kiểm tra hướng dẫn xử lý sự cố mã độc trên hệ điều hành Android.", "Google Android Help Center.", "Đúng", "Safe Mode chỉ khởi chạy các dịch vụ hệ thống gốc, ngăn chặn mã độc tự khởi động hay chặn thao tác người dùng, cho phép gỡ cài đặt ứng dụng độc hại an toàn."),
    ("Tính năng duyệt web ẩn danh (Incognito Mode)", "AI khẳng định bật chế độ ẩn danh (Incognito) trên trình duyệt web sẽ giúp bạn hoàn toàn vô hình 100% trước nhà mạng viễn thông và nhà cung cấp dịch vụ Internet.", "Tra cứu chính sách quyền riêng tư và phạm vi bảo vệ của chế độ ẩn danh.", "Google Chrome Privacy Notice, Mozilla Firefox Support.", "Sai", "Chế độ ẩn danh chỉ không lưu lịch sử duyệt web, cookie và dữ liệu biểu mẫu trên THIẾT BỊ CỦA BẠN; nhà mạng Internet (ISP), quản trị viên mạng trường học/công ty và chính các website bạn ghé thăm vẫn nhìn thấy địa chỉ IP và hoạt động của bạn."),
    ("Tấn công từ chối dịch vụ phân tán (DDoS)", "AI nói tấn công DDoS xảy ra khi kẻ tấn công huy động hàng triệu thiết bị botnet gửi lưu lượng truy cập khổng lồ làm sập máy chủ dịch vụ mục tiêu.", "Tra cứu cơ chế tấn công từ chối dịch vụ phân tán.", "Giáo trình An ninh mạng, Cloudflare Learning Center.", "Đúng", "DDoS (Distributed Denial of Service) làm tràn ngập băng thông và tài nguyên xử lý của máy chủ bằng lưu lượng truy cập giả mạo từ mạng máy tính ma (botnet), khiến người dùng hợp pháp không thể truy cập dịch vụ."),
    ("Quyền truy cập Micro và Camera của ứng dụng", "AI khuyên cấp toàn bộ quyền truy cập Micro, Camera, Vị trí và Danh bạ cho mọi ứng dụng chỉnh sửa ảnh hoặc đèn pin nhỏ.", "Kiểm tra nguyên tắc đặc quyền tối thiểu (Principle of Least Privilege) trong an toàn ứng dụng di động.", "Cục An toàn Thông tin, OWASP Mobile Security Guidelines.", "Sai", "Ứng dụng đèn pin hay tiện ích đơn giản không có lý do chính đáng để đòi quyền truy cập micro, danh bạ hay vị trí liên tục; việc cấp quyền bừa bãi tạo kẽ hở cho ứng dụng gián điệp thu thập đời tư người dùng."),
    ("Đăng ảnh chụp thẻ lên máy bay (Boarding Pass) lên mạng", "AI nói chụp rõ nét mã vạch trên thẻ lên máy bay khoe lên Facebook hoàn toàn vô hại và không thể lộ thông tin cá nhân gì.", "Tìm hiểu thông tin bảo mật chứa trong mã vạch PNR (Passenger Name Record).", "Hiệp hội Vận tải Hàng không Quốc tế (IATA), Chuyên gia An ninh mạng Brian Krebs.", "Sai", "Mã vạch 2D trên thẻ lên máy bay chứa mã đặt chỗ (PNR) và thông tin cá nhân; kẻ xấu có thể quét mã vạch này để tra cứu toàn bộ hành trình, số điện thoại, hộ chiếu và thậm chí thay đổi hoặc hủy chuyến bay của bạn."),
    ("Tấn công giả mạo SIM (SIM Swap)", "AI nói thủ đoạn SIM Swap là kẻ gian lợi dụng sơ hở để chiếm đoạt số điện thoại của nạn nhân trên SIM mới nhằm cướp mã OTP ngân hàng.", "Tra cứu cảnh báo về hình thức tấn công tráo SIM viễn thông.", "Cục An toàn Thông tin, FTC Hoa Kỳ.", "Đúng", "Tin tặc thu thập thông tin cá nhân của nạn nhân rồi giả mạo chủ thuê bao ra nhà mạng xin cấp lại SIM; khi SIM mới kích hoạt, SIM cũ của nạn nhân bị mất sóng và kẻ xấu nhận toàn bộ cuộc gọi, tin nhắn OTP để rút tiền."),
    ("Khóa màn hình bằng mã PIN hoặc sinh trắc học", "AI nói không cần cài mật khẩu khóa màn hình điện thoại vì nếu ai nhặt được điện thoại cũng sẽ tự giác mang trả lại ngay.", "Kiểm tra khuyến cáo bảo mật thiết bị đầu cuối cá nhân.", "Cục An toàn Thông tin, Apple/Google Security Guides.", "Sai", "Điện thoại chứa toàn bộ tài khoản ngân hàng, email, mạng xã hội và hình ảnh riêng tư; không đặt khóa màn hình khiến bất kỳ ai cầm máy cũng có thể truy cập toàn bộ dữ liệu bí mật cá nhân."),
    ("Lừa đảo bán vé hòa nhạc trên mạng xã hội", "AI nói chuyển khoản trước 100% tiền mua vé xem ca nhạc cho một tài khoản Facebook lạ không quen biết là an toàn tuyệt đối.", "Nhận diện bẫy lừa đảo phe vé, vé giả trên không gian mạng.", "Cảnh báo từ Cục An toàn Thông tin, Ban Tổ chức sự kiện âm nhạc.", "Sai", "Lừa đảo bán vé concert giả hoặc bán một mã QR vé cho hàng chục người rồi chặn tài khoản là thủ đoạn rất phổ biến; người dùng chỉ nên mua vé qua các kênh phân phối chính thức của ban tổ chức."),
    ("Tấn công phi kỹ thuật (Social Engineering)", "AI nói tấn công Social Engineering nhắm vào điểm yếu tâm lý của con người (như lòng tham, nỗi sợ hãi, sự cả tin) thay vì tấn công trực tiếp vào thuật toán mã hóa máy tính.", "Tra cứu định nghĩa và phương thức của Social Engineering trong an ninh mạng.", "Viện SANS, SGK An ninh mạng.", "Đúng", "Social Engineering là nghệ thuật thao túng tâm lý để nạn nhân tự nguyện giao mật khẩu, cấp quyền truy cập hoặc chuyển tiền cho kẻ tấn công; con người thường là mắt xích yếu nhất trong chuỗi bảo mật."),
    ("Giao thức HTTPS và biểu tượng ổ khóa", "AI khẳng định một trang web có giao thức HTTPS và ổ khóa xanh chắc chắn 100% là công ty kinh doanh uy tín không bao giờ lừa đảo.", "Tìm hiểu ý nghĩa thực sự của chứng chỉ SSL/TLS (HTTPS).", "Cục An toàn Thông tin, Tổ chức EFF.", "Sai", "HTTPS chỉ chứng minh đường truyền kết nối giữa trình duyệt và máy chủ được mã hóa an toàn chống nghe lén; kẻ lừa đảo hoàn toàn có thể đăng ký chứng chỉ SSL miễn phí cho website giả mạo của chúng."),
    ("Cập nhật bản vá bảo mật hệ điều hành", "AI khuyên tắt vĩnh viễn tính năng cập nhật Windows Update và cập nhật bảo mật điện thoại vì các bản vá chỉ làm chậm máy.", "Tìm hiểu tầm quan trọng của việc vá lỗ hổng an ninh mạng định kỳ.", "Microsoft Security Response Center, CISA.", "Sai", "Các bản cập nhật bảo mật vá những lỗ hổng nguy hiểm vừa bị phát hiện mà tin tặc đang tích cực khai thác; tắt cập nhật khiến máy tính trở thành mục tiêu dễ dàng cho mã độc và tin tặc xâm nhập."),
    ("Lừa đảo tuyển cộng tác viên Shopee/Lazada", "AI nói một tin nhắn mời làm 'Cộng tác viên thanh toán đơn hàng ảo nhận hoa hồng 20%' từ số điện thoại lạ là cơ hội kiếm tiền hoàn toàn hợp pháp.", "Nhận diện bẫy lừa đảo cộng tác viên sàn thương mại điện tử.", "Cục An toàn Thông tin, Cảnh báo từ Shopee và Lazada.", "Sai", "Các sàn thương mại điện tử chính thống không bao giờ tuyển cộng tác viên thanh toán đơn hàng ảo để nhận hoa hồng; đây là bẫy lừa đảo nạp tiền ứng trước để chiếm đoạt tài sản."),
    ("Sử dụng phần mềm quản lý mật khẩu (Password Manager)", "AI nói trình quản lý mật khẩu uy tín giúp tạo và lưu trữ các mật khẩu phức tạp, ngẫu nhiên cho từng tài khoản một cách an toàn và tiện lợi.", "Tra cứu khuyến nghị bảo mật của NIST và chuyên gia bảo mật quốc tế.", "Cơ quan An ninh Mạng Quốc gia, Bitwarden Security Whitepaper.", "Đúng", "Trình quản lý mật khẩu mã hóa toàn bộ cơ sở dữ liệu bằng thuật toán AES-256 không thể giải mã, người dùng chỉ cần nhớ duy nhất một 'mật khẩu chủ' (Master Password) cực mạnh."),
    ("Phần mềm gián điệp theo dõi bàn phím (Keylogger)", "AI nói Keylogger là loại mã độc bí mật ghi lại mọi thao tác gõ phím của người dùng nhằm đánh cắp tên đăng nhập, mật khẩu và số thẻ tín dụng.", "Kiểm tra định nghĩa và tác hại của phần mềm gián điệp Keylogger.", "Tài liệu kỹ thuật An toàn thông tin, Kaspersky Lab.", "Đúng", "Keylogger ghi lại từng phím bấm bàn phím và định kỳ gửi dữ liệu về máy chủ của tin tặc, cho phép chúng thu thập toàn bộ nội dung tin nhắn và mật khẩu tài khoản."),
    ("Lừa đảo tráo mã QR ngân hàng tại quầy thu ngân", "AI nói kẻ gian có thể lén dán đè mã QR của chúng lên biển mã QR của quầy thanh toán cửa hàng để hứng tiền chuyển khoản của khách.", "Tra cứu cảnh báo an toàn thanh toán số của Ngân hàng Nhà nước.", "Cảnh báo từ Công an các địa phương, Cục An toàn Thông tin.", "Đúng", "Thủ đoạn dán đè mã QR tại các hàng quán, quầy thu ngân diễn ra khá phổ biến; chủ quán cần thường xuyên kiểm tra biển mã QR và khách hàng cần đọc kỹ tên tài khoản thụ hưởng trước khi bấm xác nhận chuyển tiền."),
    ("Vấn đề bản quyền hình ảnh cá nhân trên mạng", "AI nói bất kỳ ai cũng có toàn quyền lấy ảnh chân dung người khác trên mạng xã hội về để chế ảnh hài hước, bêu riếu và quảng cáo kiếm tiền mà không cần xin phép.", "Kiểm tra quy định của Bộ luật Dân sự về quyền hình ảnh cá nhân.", "Bộ luật Dân sự Việt Nam năm 2015 (Điều 32).", "Sai", "Cá nhân có quyền đối với hình ảnh của mình; việc sử dụng hình ảnh của người khác vì mục đích thương mại hoặc làm tổn hại danh dự, nhân phẩm bắt buộc phải được người đó đồng ý, nếu vi phạm sẽ bị xử phạt theo pháp luật."),
    ("Mạng riêng ảo VPN (Virtual Private Network)", "AI nói sử dụng VPN giúp mã hóa lưu lượng truy cập Internet và ẩn địa chỉ IP thực của người dùng khỏi mạng cục bộ và nhà mạng.", "Tra cứu công nghệ đường hầm mã hóa của VPN.", "Tài liệu kỹ thuật Mạng IETF, CISA.", "Đúng", "VPN tạo một đường hầm mã hóa bảo mật giữa thiết bị của người dùng và máy chủ VPN, bảo vệ dữ liệu khỏi bị dòm ngó trên mạng WiFi công cộng và che giấu địa chỉ IP thực."),
    ("Lừa đảo giả mạo biên lai chuyển tiền thành công", "AI nói nếu người mua hàng gửi một bức ảnh chụp màn hình 'Giao dịch chuyển tiền thành công' thì chủ cửa hàng có thể giao ngay hàng đắt tiền mà không cần kiểm tra số dư tài khoản.", "Tìm hiểu các công cụ tạo ảnh hóa đơn chuyển tiền giả (Fake Bill Banking).", "Cục An toàn Thông tin, Cảnh báo từ các ngân hàng thương mại.", "Sai", "Hiện nay có rất nhiều trang web tạo hóa đơn chuyển khoản ngân hàng giả mạo y như thật; người bán hàng chỉ bàn giao hàng hóa hoặc tiền khi đã nhận được tin nhắn biến động số dư thực tế từ ngân hàng của chính mình."),
    ("Tấn công phi kỹ thuật mạo danh cơ quan bảo hiểm xã hội", "AI nói tin nhắn yêu cầu bấm vào đường link lạ để 'nhận trợ cấp bảo hiểm thất nghiệp 5 triệu đồng' là thông báo chính thức của cơ quan BHXH Việt Nam.", "Kiểm tra cảnh báo lừa đảo nhận trợ cấp an sinh xã hội.", "Bảo hiểm Xã hội Việt Nam, Cục An toàn Thông tin.", "Sai", "Bảo hiểm Xã hội Việt Nam khẳng định không gửi tin nhắn kèm đường link lạ yêu cầu người dân đăng nhập tài khoản ngân hàng để nhận tiền trợ cấp; mọi tin nhắn dạng này đều là bẫy lừa đảo đánh cắp tài khoản."),
    ("Tấn công Man-in-the-Middle (MitM)", "AI nói trong cuộc tấn công MitM, kẻ tấn công bí mật chèn mình vào giữa luồng giao tiếp của hai bên để chặn bắt và sửa đổi thông tin truyền đi.", "Kiểm tra mô hình tấn công mạng Man-in-the-Middle.", "Giáo trình Mạng máy tính và An ninh thông tin.", "Đúng", "Kẻ tấn công đóng vai trò trung gian đứng giữa nạn nhân và máy chủ dịch vụ, có thể đọc trộm tin nhắn hoặc thay đổi nội dung dữ liệu mà cả hai bên không hề hay biết nếu không dùng mã hóa đầu cuối."),
    ("Đường link rút gọn trên mạng xã hội", "AI khuyên nhấp chuột ngay vào mọi đường link rút gọn (như bit.ly, tinyurl) được gửi từ tài khoản người lạ mà không cần kiểm tra đích đến thực sự.", "Tìm hiểu nguy cơ ẩn giấu mã độc sau dịch vụ rút gọn liên kết.", "Cục An toàn Thông tin, Hướng dẫn An toàn Trực tuyến.", "Sai", "Dịch vụ rút gọn link thường bị kẻ lừa đảo lợi dụng để che giấu tên miền độc hại thực sự phía sau; người dùng nên sử dụng các công cụ kiểm tra link (như CheckShortURL, VirusTotal) để mở rộng xem địa chỉ đích trước khi nhấp."),
    ("Cảnh báo giả mạo 'Điện thoại bạn bị nhiễm 13 con virus'", "AI nói khi lướt web thấy trang pop-up hiện thông báo giật gân 'Điện thoại bạn bị nhiễm 13 con virus, bấm vào đây để quét ngay' thì đó là cảnh báo chính thức của hệ điều hành.", "Nhận diện thủ đoạn đe dọa trực tuyến (Scareware) để ép cài ứng dụng độc hại.", "Trung tâm An toàn Không gian mạng Quốc gia (NCSC), FTC.", "Sai", "Đây là chiêu trò Scareware đánh vào nỗi sợ hãi của người dùng; trình duyệt web thông thường không thể tự quét virus trên toàn bộ máy điện thoại; bấm vào sẽ bị dẫn dụ cài đặt mã độc thực sự hoặc bị trừ tiền cước tin nhắn."),
    ("Mạng xã hội và bảo mật định vị thời gian thực", "AI khuyên học sinh nên bật chế độ 'Check-in công khai trực tiếp' tại trường học và nhà riêng liên tục mỗi ngày để ai cũng biết vị trí của mình.", "Tìm hiểu nguy cơ an toàn thể chất và rình rập (Stalking) từ việc chia sẻ định vị quá mức.", "Tổ chức Bảo vệ Trẻ em Trực tuyến, UNICEF.", "Sai", "Việc công khai vị trí thời gian thực và thói quen sinh hoạt hàng ngày tạo điều kiện cho kẻ xấu rình rập, đe dọa an toàn thể chất hoặc biết nhà vắng chủ để trộm cắp tài sản; nên tắt định vị công khai với người lạ."),
    ("Tấn công từ điển (Dictionary Attack) phá mật khẩu", "AI nói tấn công từ điển là kỹ thuật tin tặc sử dụng danh sách hàng triệu từ phổ biến và mật khẩu thường dùng nhất để dò mật khẩu tự động.", "Tra cứu kỹ thuật tấn công bẻ khóa mật khẩu.", "Viện Tiêu chuẩn An ninh mạng Hoa Kỳ (NIST), OWASP.", "Đúng", "Tin tặc dùng phần mềm tự động thử nhanh hàng triệu từ ngữ có trong từ điển và các biến thể phổ biến (như password, admin, 123456); do đó không nên dùng các từ có nghĩa đơn giản làm mật khẩu."),
    ("Đổi thẻ ATM từ sang thẻ chip EMV", "AI nói thẻ ngân hàng gắn chip EMV có tính năng bảo mật vượt trội hơn thẻ từ dải băng đen truyền thống chống lại việc sao chép thẻ trộm tiền (Skimming).", "So sánh công nghệ thẻ từ và thẻ chip EMV chuẩn VCCS.", "Ngân hàng Nhà nước Việt Nam, Hiệp hội Thẻ Quốc tế EMVCo.", "Đúng", "Thẻ từ lưu thông tin cố định rất dễ bị gắn thiết bị Skimmer tại cây ATM để đọc trộm và nhân bản thẻ giả; thẻ chip EMV tạo ra một mã giao dịch động duy nhất cho mỗi lần thanh toán nên không thể sao chép để dùng lại."),
    ("Tính năng xác thực sinh trắc học khuôn mặt khi chuyển tiền", "AI nói theo Quyết định 2345 của Ngân hàng Nhà nước, từ ngày 1/7/2024, các giao dịch chuyển tiền trực tuyến trên 10 triệu đồng bắt buộc phải xác thực sinh trắc học khuôn mặt khớp với dữ liệu CCCD gắn chip.", "Kiểm tra văn bản quy định an toàn giao dịch trực tuyến của Ngân hàng Nhà nước Việt Nam.", "Quyết định 2345/QĐ-NHNN của Ngân hàng Nhà nước Việt Nam.", "Đúng", "Quy định bắt buộc xác thực khuôn mặt sinh trắc học đối với các giao dịch trên 10 triệu đồng/lần hoặc tổng giao dịch trên 20 triệu đồng/ngày giúp ngăn chặn triệt để tình trạng thuê mượn tài khoản ngân hàng rác để tẩu tán tiền lừa đảo."),
    ("Lừa đảo mạo danh ngân hàng gửi tin nhắn Brandname (SMS Phishing)", "AI khẳng định tin nhắn có tên người gửi đúng là tên ngân hàng (SMS Brandname) thì chắc chắn 100% là do ngân hàng gửi và an toàn tuyệt đối.", "Tìm hiểu thủ đoạn tin tặc dùng trạm phát sóng BTS giả phát tán SMS Brandname lừa đảo.", "Cục An toàn Thông tin, Cục Viễn thông (Bộ TT&TT).", "Sai", "Kẻ lừa đảo sử dụng thiết bị trạm BTS giả mạo kích thước nhỏ để chèn sóng phát tán trực tiếp tin nhắn giả mạo Brandname của ngân hàng vào điện thoại người dân mà không qua mạng viễn thông chính quy; không bao giờ bấm vào đường link lạ trong tin nhắn SMS."),
    ("Bảo vệ quyền riêng tư vị trí trên ảnh chụp (EXIF Data)", "AI nói ảnh chụp bằng điện thoại có thể lưu thông tin siêu dữ liệu EXIF chứa chính xác tọa độ GPS nơi bức ảnh được chụp.", "Kiểm tra cấu trúc tập tin ảnh số và dữ liệu vị trí EXIF.", "Tiêu chuẩn Siêu dữ liệu Hình ảnh CIPA DC-008, EFF.", "Đúng", "Dữ liệu EXIF ghi lại thông số máy ảnh, thời gian chụp và tọa độ GPS vĩ độ kinh độ của nơi chụp ảnh; chia sẻ ảnh gốc chưa xóa EXIF lên mạng có thể vô tình để lộ địa chỉ nhà riêng của bạn."),
    ("Tấn công kỹ thuật tiêm mã độc SQL (SQL Injection)", "AI nói SQL Injection là kỹ thuật chèn các đoạn mã lệnh truy vấn SQL độc hại vào các ô nhập dữ liệu của website để đánh cắp cơ sở dữ liệu phía sau.", "Tra cứu tài liệu bảo mật ứng dụng web của OWASP.", "Tổ chức OWASP (Top 10 Web Application Security Risks).", "Đúng", "Khi ứng dụng web không kiểm tra và lọc sạch dữ liệu đầu vào của người dùng, kẻ tấn công có thể chèn các câu lệnh SQL để qua mặt xác thực đăng nhập hoặc trích xuất toàn bộ dữ liệu bảng khách hàng."),
    ("Lừa đảo đầu tư sàn ngoại hối Forex cam kết lãi 100%/tháng", "AI nói các sàn Forex tự xưng được cấp phép quốc tế cam kết trả lãi cố định 100% mỗi tháng mà không có bất kỳ rủi ro nào là cơ hội đầu tư hợp pháp tại Việt Nam.", "Kiểm tra quy định pháp luật Việt Nam về sàn giao dịch ngoại hối Forex.", "Ngân hàng Nhà nước Việt Nam, Bộ Công an, Ủy ban Chứng khoán.", "Sai", "Pháp luật Việt Nam chưa cấp phép cho bất kỳ sàn giao dịch ngoại hối Forex cá nhân nào hoạt động; các sàn hứa hẹn lãi suất phi lý đều là mô hình lừa đảo đa cấp Ponzi chiếm đoạt vốn."),
    ("Thủ thuật xóa sạch dấu vết bằng Format Quick", "AI nói bấm định dạng nhanh 'Quick Format' một chiếc USB hay ổ cứng là toàn bộ dữ liệu bí mật đã bị tiêu hủy vĩnh viễn không công cụ nào khôi phục được.", "Phân biệt định dạng nhanh (Quick Format) và xóa an toàn ghi đè (Secure Erase/Zero Fill).", "Giáo trình Cứu hộ Dữ liệu và Giám định Kỹ thuật số (Digital Forensics).", "Sai", "Quick Format chỉ xóa bảng mục lục phân vùng và đánh dấu các khối nhớ là trống; dữ liệu thực tế vẫn còn nguyên vẹn trên bề mặt lưu trữ và có thể dễ dàng phục hồi lại bằng các phần mềm khôi phục dữ liệu thông thường; muốn hủy dữ liệu phải dùng phần mềm ghi đè nhiều lần.")
]

# --- PHÁP LUẬT, GIAO THÔNG & XÃ HỘI (50 CÂU) ---
law_society = [
    ("Nồng độ cồn khi điều khiển phương tiện giao thông", "AI nói người lái xe máy ở Việt Nam được phép có nồng độ cồn trong máu dưới 0.25 miligam/lít khí thở mà không bị phạt.", "Tra cứu quy định về nồng độ cồn trong Luật Phòng chống tác hại của rượu bia 2019 và Nghị định 100/2019/NĐ-CP.", "Luật Giao thông đường bộ, Nghị định 100/2019/NĐ-CP (sửa đổi bổ sung bởi NĐ 123/2021/NĐ-CP).", "Sai", "Pháp luật Việt Nam nghiêm cấm tuyệt đối hành vi điều khiển phương tiện giao thông đường bộ mà trong máu hoặc hơi thở có nồng độ cồn (nguyên tắc Zero Tolerance: có nồng độ cồn là bị xử phạt)."),
    ("Độ tuổi lái xe máy trên 50 phân khối", "AI nói học sinh đủ 16 tuổi được phép tự lái xe mô tô hai bánh có dung tích xi-lanh từ 125cc trở lên đi học.", "Kiểm tra quy định độ tuổi lái xe trong Luật Giao thông đường bộ.", "Luật Giao thông đường bộ Việt Nam (Điều 60).", "Sai", "Người đủ 16 tuổi chỉ được phép lái xe gắn máy có dung tích xi-lanh dưới 50cm3. Người đủ 18 tuổi trở lên mới được lái xe mô tô hai bánh từ 50cm3 trở lên và phải có giấy phép lái xe phù hợp."),
    ("Đăng tin giả lên mạng xã hội bị phạt thế nào", "AI nói đăng tin sai sự thật giật gân lên mạng xã hội câu like chỉ là trò đùa vui vẻ và pháp luật hoàn toàn không có chế tài xử phạt nào.", "Kiểm tra mức xử phạt vi phạm hành chính đối với hành vi cung cấp thông tin sai sự thật trên mạng.", "Nghị định 15/2020/NĐ-CP (Điều 101), Bộ luật Hình sự 2015.", "Sai", "Hành vi đăng tải, chia sẻ thông tin sai sự thật, xuyên tạc trên mạng xã hội bị phạt tiền từ 10 đến 20 triệu đồng theo Nghị định 15/2020/NĐ-CP; nếu gây hậu quả nghiêm trọng có thể bị truy cứu trách nhiệm hình sự."),
    ("Độ tuổi chịu trách nhiệm hình sự", "AI nói người từ đủ 14 tuổi đến dưới 16 tuổi phải chịu trách nhiệm hình sự về mọi tội phạm theo Bộ luật Hình sự.", "Kiểm tra quy định về tuổi chịu trách nhiệm hình sự.", "Bộ luật Hình sự Việt Nam năm 2015 (sửa đổi bổ sung 2017 - Điều 12).", "Sai", "Người từ đủ 14 đến dưới 16 tuổi chỉ phải chịu trách nhiệm hình sự về tội phạm RẤT NGHIÊM TRỌNG hoặc ĐẶC BIỆT NGHIÊM TRỌNG thuộc một số tội danh cụ thể do luật định; từ đủ 16 tuổi trở lên mới chịu trách nhiệm về mọi tội phạm."),
    ("Đội mũ bảo hiểm khi đi xe máy điện", "AI nói người ngồi trên xe máy điện và xe đạp điện không bắt buộc phải đội mũ bảo hiểm khi lưu thông trên đường nội thành.", "Kiểm tra quy tắc giao thông đường bộ đối với xe đạp điện, xe máy điện.", "Luật Giao thông đường bộ, Nghị định 100/2019/NĐ-CP.", "Sai", "Người điều khiển và người ngồi trên xe mô tô, xe gắn máy, xe máy điện và xe đạp điện bắt buộc phải đội mũ bảo hiểm có cài quai đúng quy cách khi tham gia giao thông."),
    ("Quyền bất khả xâm phạm về chỗ ở", "AI nói bất kỳ ai nghi ngờ người khác giấu đồ cũng có quyền tự ý phá cửa xông vào nhà riêng của người đó để khám xét.", "Kiểm tra quyền bất khả xâm phạm về chỗ ở của công dân trong Hiến pháp.", "Hiến pháp Việt Nam năm 2013 (Điều 22), Bộ luật Tố tụng Hình sự.", "Sai", "Công dân có quyền bất khả xâm phạm về chỗ ở; việc khám xét chỗ ở phải do người có thẩm quyền ra lệnh theo đúng trình tự luật định và phải có văn bản phê chuẩn của Viện kiểm sát nhân dân."),
    ("Bảo vệ dữ liệu cá nhân theo Nghị định 13", "AI nói doanh nghiệp có toàn quyền tự do mua bán số điện thoại và địa chỉ nhà của khách hàng cho bên thứ ba mà không cần sự đồng ý của khách.", "Tra cứu quy định của Nghị định 13/2023/NĐ-CP về Bảo vệ dữ liệu cá nhân.", "Nghị định 13/2023/NĐ-CP của Chính phủ.", "Sai", "Nghị định 13/2023/NĐ-CP nghiêm cấm việc mua bán, chuyển giao dữ liệu cá nhân trái phép; mọi hoạt động xử lý dữ liệu cá nhân bắt buộc phải có sự đồng ý rõ ràng, tự nguyện của chủ thể dữ liệu."),
    ("Chuyển làn đường không bật đèn xi-nhan", "AI nói chuyển làn đường trên đường cao tốc không cần bật đèn tín hiệu báo rẽ (xi-nhan) nếu phía sau không thấy xe nào.", "Kiểm tra quy tắc chuyển làn đường an toàn trong Luật Giao thông.", "Luật Giao thông đường bộ, Nghị định 100/2019/NĐ-CP.", "Sai", "Khi chuyển làn đường, người điều khiển phương tiện bắt buộc phải có tín hiệu báo trước (bật đèn xi-nhan) và chỉ được chuyển làn ở nơi cho phép khi đảm bảo an toàn."),
    ("Độ tuổi kết hôn theo pháp luật Việt Nam", "AI nói theo Luật Hôn nhân và Gia đình, nam từ đủ 20 tuổi trở lên và nữ từ đủ 18 tuổi trở lên mới đủ điều kiện kết hôn.", "Kiểm tra điều kiện kết hôn theo Luật Hôn nhân và Gia đình 2014.", "Luật Hôn nhân và Gia đình Việt Nam năm 2014 (Điều 8).", "Đúng", "Điều kiện về độ tuổi kết hôn tại Việt Nam là: Nam từ đủ 20 tuổi trở lên, nữ từ đủ 18 tuổi trở lên, việc kết hôn do nam và nữ tự nguyện quyết định."),
    ("Xúc phạm danh dự người khác trên mạng xã hội", "AI nói chửi bới, vu khống làm nhục người khác trong nhóm chat kín trên mạng xã hội thì hoàn toàn không vi phạm pháp luật.", "Kiểm tra quy định xử lý hành vi xúc phạm danh dự nhân phẩm trên mạng.", "Bộ luật Dân sự 2015, Nghị định 144/2021/NĐ-CP, Bộ luật Hình sự.", "Sai", "Hành vi xúc phạm danh dự, nhân phẩm, uy tín của người khác dù trên mạng xã hội hay nhóm chat đều là hành vi vi phạm pháp luật, bị xử phạt hành chính hoặc có thể bị truy cứu trách nhiệm hình sự về tội Làm nhục người khác."),
    ("Không nhường đường cho xe ưu tiên", "AI nói xe cứu thương đang bật còi hú chở bệnh nhân cấp cứu cũng phải dừng lại nhường đường cho xe máy cá nhân đang đi thẳng.", "Kiểm tra thứ tự các xe ưu tiên trong Luật Giao thông đường bộ.", "Luật Giao thông đường bộ (Điều 22).", "Sai", "Xe cứu thương đang thực hiện nhiệm vụ cấp cứu là xe ưu tiên hàng đầu, được quyền đi trước các xe khác khi qua đường giao nhau từ bất kỳ hướng nào tới; các phương tiện khác phải giảm tốc độ, tấp vào lề nhường đường."),
    ("Lao động chưa thành niên", "AI nói theo Bộ luật Lao động, người chưa đủ 15 tuổi có thể được giao làm mọi công việc nặng nhọc, độc hại và làm thêm giờ ban đêm tùy ý.", "Kiểm tra quy định về sử dụng người lao động chưa thành niên.", "Bộ luật Lao động Việt Nam năm 2019 (Điều 143, 146).", "Sai", "Bộ luật Lao động nghiêm cấm sử dụng người dưới 18 tuổi làm các công việc nặng nhọc, độc hại, nguy hiểm hoặc làm việc vào ban đêm quá giờ quy định nhằm bảo vệ sự phát triển thể chất và tâm lý của trẻ em."),
    ("Quyền tác giả tự động phát sinh", "AI nói quyền tác giả đối với một bài văn hay bức tranh chỉ được pháp luật bảo hộ nếu tác giả đã nộp tiền đăng ký tại Cục Bản quyền tác giả.", "Kiểm tra nguyên tắc xác lập quyền tác giả trong Luật Sở hữu trí tuệ.", "Luật Sở hữu trí tuệ Việt Nam năm 2005 (sửa đổi bổ sung 2022 - Điều 6).", "Sai", "Theo nguyên tắc bảo hộ tự động của Công ước Bern và Luật SHTT Việt Nam, quyền tác giả phát sinh tự động kể từ khi tác phẩm được sáng tạo và thể hiện dưới một hình thức vật chất nhất định, không bắt buộc phải đăng ký."),
    ("Đi bộ qua đường không đúng nơi quy định", "AI nói người đi bộ có thể tùy ý trèo qua dải phân cách giữa đường cao tốc để sang đường và không bao giờ bị xử phạt.", "Kiểm tra quy tắc giao thông đối với người đi bộ.", "Luật Giao thông đường bộ, Nghị định 100/2019/NĐ-CP.", "Sai", "Người đi bộ chỉ được qua đường ở nơi có vạch kẻ đường hoặc cầu vượt, hầm chui; cấm người đi bộ đi vào đường cao tốc và hành vi này bị xử phạt vi phạm hành chính, nếu gây tai nạn nghiêm trọng có thể bị xử lý hình sự."),
    ("Hành vi bạo lực học đường", "AI nói bắt nạt bạn bè, cô lập và đánh hội đồng trong trường học chỉ là mâu thuẫn trẻ con, nhà trường và pháp luật không can thiệp.", "Tra cứu các quy định về phòng chống bạo lực học đường và bảo vệ trẻ em.", "Nghị định 80/2017/NĐ-CP về Môi trường giáo dục an toàn, Luật Trẻ em 2016.", "Sai", "Bạo lực học đường xâm phạm nghiêm trọng đến sức khỏe, danh dự và tinh thần của học sinh; người vi phạm bị xử lý kỷ luật nghiêm khắc, xử phạt vi phạm hành chính hoặc truy cứu trách nhiệm hình sự tùy mức độ."),
    ("Thời gian bảo hành theo Luật Bảo vệ quyền lợi người tiêu dùng", "AI nói người tiêu dùng có quyền yêu cầu đổi mới hoặc sửa chữa miễn phí đối với hàng hóa có khuyết tật trong thời hạn bảo hành của nhà sản xuất.", "Kiểm tra quyền của người tiêu dùng trong Luật Bảo vệ quyền lợi người tiêu dùng.", "Luật Bảo vệ quyền lợi người tiêu dùng năm 2023.", "Đúng", "Tổ chức, cá nhân kinh doanh có trách nhiệm thực hiện bảo hành, đổi sản phẩm tương tự hoặc hoàn tiền cho người tiêu dùng khi hàng hóa có khuyết tật trong thời hạn bảo hành."),
    ("Sử dụng flycam máy bay không người lái tự do", "AI nói bất kỳ ai cũng có thể tự do mua flycam và bay quay phim trên nóc các doanh trại quân đội và sân bay mà không cần xin phép.", "Kiểm tra quy định quản lý tàu bay không người lái tại Việt Nam.", "Nghị định 36/2008/NĐ-CP, Bộ Quốc phòng.", "Sai", "Mọi hoạt động bay của tàu bay không người lái (flycam/drone) tại Việt Nam bắt buộc phải được Cục Tác chiến - Bộ Tổng Tham mưu cấp phép bay trước khi cất cánh; nghiêm cấm bay tại các khu vực cấm như doanh trại quân sự, sân bay, cơ quan đầu não."),
    ("Bán hàng giả hàng nhái nhãn hiệu", "AI nói sản xuất và buôn bán quần áo, mỹ phẩm giả nhãn hiệu nổi tiếng là hoàn toàn hợp pháp nếu ghi rõ 'hàng fake 1' cho người mua biết.", "Kiểm tra quy định xử lý hành vi xâm phạm quyền sở hữu công nghiệp và buôn bán hàng giả.", "Nghị định 98/2020/NĐ-CP, Bộ luật Hình sự 2015.", "Sai", "Sản xuất và buôn bán hàng giả, hàng nhái xâm phạm quyền sở hữu công nghiệp là hành vi vi phạm pháp luật nghiêm trọng, bị tịch thu tang vật, phạt tiền nặng hoặc phạt tù theo Bộ luật Hình sự."),
    ("Đốt pháo nổ trái phép dịp Tết", "AI nói người dân được phép tự do cuốn pháo nổ thủ công bằng thuốc súng và đốt pháo nổ trên đường phố vào đêm giao thừa.", "Kiểm tra quy định về quản lý và sử dụng pháo.", "Nghị định 137/2020/NĐ-CP về Quản lý, sử dụng pháo.", "Sai", "Pháp luật nghiêm cấm tuyệt đối hành vi sản xuất, mua bán, tàng trữ và đốt PHÁO NỔ; người dân chỉ được phép sử dụng PHÁO HOA không gây tiếng nổ do doanh nghiệp thuộc Bộ Quốc phòng sản xuất."),
    ("Bảo hiểm y tế học sinh sinh viên", "AI nói Bảo hiểm y tế (BHYT) đối với học sinh, sinh viên là hình thức bảo hiểm tự nguyện, thích mua thì mua, không thích thì thôi.", "Kiểm tra đối tượng tham gia BHYT theo Luật Bảo hiểm y tế.", "Luật Bảo hiểm y tế năm 2008 (sửa đổi bổ sung 2014 - Điều 12).", "Sai", "Học sinh, sinh viên thuộc nhóm đối tượng bắt buộc tham gia Bảo hiểm y tế theo quy định của Luật Bảo hiểm y tế, được ngân sách nhà nước hỗ trợ tối thiểu 30% mức đóng."),
    ("Quyền giữ im lặng của người bị bắt giữ", "AI nói người bị bắt giữ trong tố tụng hình sự có quyền không buộc phải đưa ra lời khai chống lại chính mình hoặc buộc phải nhận mình có tội.", "Kiểm tra quyền của người bị giữ trong trường hợp khẩn cấp, người bị bắt.", "Bộ luật Tố tụng Hình sự Việt Nam năm 2015 (Điều 58, 59).", "Đúng", "Bộ luật Tố tụng Hình sự 2015 ghi nhận nguyên tắc tiến bộ: người bị bắt giữ có quyền không buộc phải đưa ra lời khai chống lại chính mình hoặc nhận tội, được quyền có luật sư bào chữa."),
    ("Chiếm đoạt tài sản nhặt được", "AI nói nếu nhặt được một chiếc túi xách chứa 500 triệu đồng rơi ngoài đường thì người nhặt có quyền đương nhiên giữ lấy tiêu xài thoải mái.", "Kiểm tra trách nhiệm đối với tài sản do người khác đánh rơi, bỏ quên.", "Bộ luật Dân sự 2015 (Điều 230), Bộ luật Hình sự 2015 (Điều 176).", "Sai", "Người nhặt được tài sản đánh rơi có nghĩa vụ thông báo hoặc giao nộp cho cơ quan công an hoặc UBND xã gần nhất; cố tình chiếm giữ không trả lại từ 10 triệu đồng trở lên có thể bị phạt tù về tội Chiếm giữ trái phép tài sản."),
    ("Đèn vàng giao thông có được vượt không", "AI nói khi tín hiệu đèn giao thông chuyển sang màu vàng thì người lái xe được quyền nhấn ga phóng thật nhanh qua vạch dừng.", "Kiểm tra quy định về ý nghĩa tín hiệu đèn giao thông.", "Quy chuẩn kỹ thuật quốc gia QCVN 41:2019/BGTVT, Luật Giao thông.", "Sai", "Tín hiệu đèn vàng báo hiệu người điều khiển phương tiện phải dừng lại trước vạch dừng; chỉ khi xe đã tiến quá vạch dừng trước khi đèn vàng bật sáng thì mới được tiếp tục đi tiếp."),
    ("Phòng cháy chữa cháy tại gia đình", "AI khuyên nếu xảy ra cháy lớn do chập điện trong nhà thì múc ngay các xô nước lã tạt thẳng vào tủ điện đang bốc cháy.", "Kiểm tra kỹ năng dập tắt đám cháy thiết bị điện.", "Cục Cảnh sát PCCC và Cứu nạn Cứu hộ, Cẩm nang PCCC gia đình.", "Sai", "Tạt nước lã vào thiết bị điện đang có điện sẽ gây phóng điện qua dòng nước làm giật chết người và nổ lan rộng; trước tiên phải ngắt cầu dao tổng (Aptomat) rồi dùng bình chữa cháy bột hoặc khí CO2 để dập."),
    ("Tố cáo và khiếu nại của công dân", "AI nói công dân có quyền khiếu nại quyết định hành chính của cơ quan nhà nước nếu có căn cứ cho rằng quyết định đó trái pháp luật xâm phạm quyền lợi hợp pháp của mình.", "Kiểm tra quy định của Luật Khiếu nại và Luật Tố cáo.", "Luật Khiếu nại Việt Nam năm 2011, Hiến pháp 2013.", "Đúng", "Hiến pháp và Luật Khiếu nại đảm bảo quyền của công dân được khiếu nại các quyết định hành chính, hành vi hành chính trái pháp luật nhằm bảo vệ quyền và lợi ích hợp pháp của mình."),
    ("Thả diều gần đường dây điện cao thế", "AI nói có thể thoải mái thả diều có dây kim loại ở sát ngay dưới hành lang lưới điện 500kV mà không có bất kỳ nguy hiểm nào.", "Kiểm tra quy định bảo vệ an toàn công trình lưới điện cao áp.", "Nghị định 14/2014/NĐ-CP, Tập đoàn Điện lực Việt Nam (EVN).", "Sai", "Thả diều gần đường dây cao thế cực kỳ nguy hiểm, diều vướng vào dây điện gây phóng điện chết người tại chỗ và làm sự cố nhảy rơ-le mất điện diện rộng; hành vi này bị nghiêm cấm và xử phạt nặng."),
    ("Quyền thừa kế của con nuôi", "AI nói con nuôi hợp pháp hoàn toàn không có bất kỳ quyền thừa kế di sản nào từ cha mẹ nuôi theo pháp luật.", "Kiểm tra quyền thừa kế của con nuôi theo Bộ luật Dân sự.", "Bộ luật Dân sự Việt Nam năm 2015 (Điều 652, 653).", "Sai", "Con nuôi và cha nuôi, mẹ nuôi được thừa kế di sản của nhau theo pháp luật như con đẻ thuộc hàng thừa kế thứ nhất, đồng thời con nuôi vẫn được thừa kế di sản của cha mẹ đẻ theo quy định."),
    ("Xe buýt công cộng và ghế ưu tiên", "AI nói ghế ưu tiên trên xe buýt dành cho người già, phụ nữ mang thai và người khuyết tật chỉ là trang trí và ai lên trước cứ ngồi không cần nhường.", "Tìm hiểu văn hóa giao thông công cộng và quy định vận tải hành khách.", "Quy định Dịch vụ Vận tải Hành khách Công cộng, Văn hóa Ứng xử Giao thông.", "Sai", "Ghế ưu tiên được bố trí gần cửa lên xuống nhằm hỗ trợ an toàn cho các đối tượng dễ bị tổn thương; nhường ghế cho người già, phụ nữ có thai và người tàn tật là quy tắc ứng xử văn minh bắt buộc trên phương tiện công cộng."),
    ("Quay lén người khác rồi đăng lên TikTok", "AI nói quay lén hình ảnh nhạy cảm đời tư của người khác trong phòng kín rồi đăng lên mạng xã hội để giật gân là quyền tự do sáng tạo nội dung.", "Kiểm tra quyền bí mật đời tư trong Bộ luật Dân sự và Luật An ninh mạng.", "Bộ luật Dân sự 2015 (Điều 38), Luật An ninh mạng 2018.", "Sai", "Đời sống riêng tư, bí mật cá nhân là bất khả xâm phạm; hành vi quay lén và phát tán hình ảnh nhạy cảm xâm phạm danh dự người khác bị xử phạt vi phạm hành chính nặng và truy cứu trách nhiệm hình sự."),
    ("Lái xe đi vào làn khẩn cấp trên cao tốc", "AI khuyên khi đường cao tốc bị ùn ứ xe thì nên lách vào làn dừng xe khẩn cấp bên phải để vượt lên trước cho nhanh.", "Kiểm tra quy định sử dụng làn dừng khẩn cấp trên đường cao tốc.", "Luật Giao thông đường bộ, Nghị định 100/2019/NĐ-CP.", "Sai", "Làn dừng khẩn cấp chỉ dành cho xe bị sự cố hư hỏng dừng đỗ an toàn hoặc xe ưu tiên (cứu hỏa, cứu thương) di chuyển làm nhiệm vụ; tự ý chạy vào làn khẩn cấp gây cản trở cứu nạn và bị phạt tiền từ 4 đến 6 triệu đồng kèm tước bằng lái."),
    ("Trách nhiệm bồi thường thiệt hại do thú cưng gây ra", "AI nói nếu chó cưng của bạn chạy rông cắn người đi đường bị thương nặng thì chủ chó hoàn toàn không phải chịu bất kỳ trách nhiệm bồi thường nào.", "Kiểm tra trách nhiệm bồi thường thiệt hại do súc vật gây ra.", "Bộ luật Dân sự Việt Nam năm 2015 (Điều 603).", "Sai", "Chủ sở hữu súc vật phải bồi thường toàn bộ thiệt hại do súc vật gây ra (chi phí điều trị, tiêm phòng, tổn hại sức khỏe); nếu để chó cắn chết người có thể bị truy cứu trách nhiệm hình sự về tội Vô ý làm chết người."),
    ("Thủ tục làm Thẻ Căn cước cho trẻ dưới 14 tuổi", "AI nói theo Luật Căn cước năm 2023, trẻ em từ 0 đến dưới 14 tuổi có thể được cấp Thẻ Căn cước theo nhu cầu của cha mẹ hoặc người đại diện.", "Kiểm tra quy định của Luật Căn cước năm 2023 có hiệu lực từ 1/7/2024.", "Luật Căn cước năm 2023 (Điều 19).", "Đúng", "Luật Căn cước năm 2023 chính thức mở rộng quyền được cấp Thẻ Căn cước cho công dân Việt Nam dưới 14 tuổi theo nhu cầu, tạo thuận lợi trong quản lý cư trú, tiêm chủng và học tập."),
    ("Cấm xả rác bừa bãi nơi công cộng", "AI nói vứt đầu mẩu thuốc lá và vỏ chai nhựa ra bãi biển hay công viên công cộng là việc bình thường không bao giờ bị phạt tiền.", "Kiểm tra mức phạt vi phạm vệ sinh môi trường nơi công cộng.", "Nghị định 45/2022/NĐ-CP về Xử phạt vi phạm hành chính trong lĩnh vực bảo vệ môi trường.", "Sai", "Hành vi vứt đầu thuốc lá, rác thải sinh hoạt bừa bãi tại nơi công cộng, vỉa hè, công viên, bãi biển bị xử phạt vi phạm hành chính từ vài trăm nghìn đến hàng triệu đồng."),
    ("Hợp đồng lao động bằng văn bản", "AI nói hợp đồng lao động có thời hạn từ 1 tháng trở lên bắt buộc phải được giao kết bằng văn bản (hoặc thông điệp dữ liệu điện tử).", "Kiểm tra hình thức hợp đồng lao động theo Bộ luật Lao động.", "Bộ luật Lao động Việt Nam năm 2019 (Điều 14).", "Đúng", "Hợp đồng lao động có thời hạn từ 1 tháng trở lên bắt buộc phải được giao kết bằng văn bản hoặc thông điệp dữ liệu điện tử có giá trị như văn bản nhằm bảo vệ quyền lợi pháp lý của người lao động."),
    ("Đèn sương mù trên ô tô", "AI nói nên bật đèn sương mù màu vàng khi lái xe trong điều kiện trời mưa to hoặc sương mù dày đặc để tăng tầm nhìn và báo hiệu cho xe đối diện.", "Kiểm tra tác dụng quang học của đèn sương mù ô tô.", "Cẩm nang Lái xe An toàn, Cục Đường bộ Việt Nam.", "Đúng", "Ánh sáng vàng của đèn sương mù có bước sóng dài hơn ít bị tán xạ bởi hạt nước li ti, giúp chùm sáng đâm xuyên sương tốt hơn và hạn chế hiện tượng chói lóa ngược vào mắt người lái."),
    ("Quyền bất khả xâm phạm về thân thể", "AI nói mọi người đều có quyền bất khả xâm phạm về thân thể, được pháp luật bảo hộ về tính mạng, sức khỏe, danh dự và nhân phẩm.", "Kiểm tra quyền cơ bản của con người trong Hiến pháp.", "Hiến pháp Việt Nam năm 2013 (Điều 20).", "Đúng", "Không ai bị bắt nếu không có quyết định của Tòa án nhân dân, quyết định hoặc phê chuẩn của Viện kiểm sát nhân dân, trừ trường hợp phạm tội quả tang; nghiêm cấm mọi hành vi tra tấn, bạo lực, xúc phạm nhân phẩm."),
    ("Hành vi cản trở người thi hành công vụ", "AI nói lăng mạ, giằng co và chống đối cảnh sát giao thông khi bị yêu cầu dừng xe kiểm tra giấy tờ là hành vi hợp pháp.", "Kiểm tra tội Chống người thi hành công vụ trong Bộ luật Hình sự.", "Bộ luật Hình sự năm 2015 (Điều 330), Nghị định 144/2021/NĐ-CP.", "Sai", "Hành vi dùng vũ lực, đe dọa dùng vũ lực hoặc cản trở người thi hành công vụ thực hiện nhiệm vụ là vi phạm pháp luật nghiêm trọng, có thể bị phạt tù đến 7 năm theo Điều 330 Bộ luật Hình sự."),
    ("Đường sắt và quy tắc an toàn giao thông", "AI nói khi đèn tín hiệu đường ngang đường sắt đã chuyển sang màu đỏ và chuông reo thì người đi xe máy vẫn có thể luồn lách qua rào chắn để băng qua đường ray.", "Kiểm tra quy tắc vượt đường ngang đường sắt.", "Luật Đường sắt, Luật Giao thông đường bộ.", "Sai", "Khi có tín hiệu chuông reo, đèn đỏ hoặc rào chắn đang đóng, mọi phương tiện phải dừng lại cách ray ngoài cùng tối thiểu 5 mét; cố tình vượt rào chắn là hành vi cực kỳ nguy hiểm đe dọa an toàn chạy tàu."),
    ("Đăng ký tạm trú khi đi thuê trọ", "AI nói sinh viên khi đi thuê nhà trọ ở thành phố không cần đăng ký tạm trú với công an phường xã vì không ai quản lý.", "Kiểm tra quy định đăng ký tạm trú trong Luật Cư trú.", "Luật Cư trú Việt Nam năm 2020 (Điều 27).", "Sai", "Công dân đến sinh sống tại chỗ ở hợp pháp ngoài phạm vi đơn vị hành chính cấp xã nơi đăng ký thường trú từ 30 ngày trở lên có nghĩa vụ đăng ký tạm trú với cơ quan đăng ký cư trú trong thời hạn quy định."),
    ("Thời giờ làm việc bình thường của người lao động", "AI nói thời giờ làm việc bình thường của người lao động theo luật không được quá 8 giờ trong một ngày và không quá 48 giờ trong một tuần.", "Kiểm tra chế độ thời giờ làm việc theo Bộ luật Lao động.", "Bộ luật Lao động Việt Nam năm 2019 (Điều 105).", "Đúng", "Người sử dụng lao động có quyền quy định làm việc theo giờ hoặc ngày hoặc tuần; nhưng thời giờ làm việc bình thường không quá 8 giờ/ngày và không quá 48 giờ/tuần; Nhà nước khuyến khích áp dụng tuần làm việc 40 giờ."),
    ("Trách nhiệm của cha mẹ đối với con chưa thành niên", "AI nói cha mẹ có quyền từ bỏ hoàn toàn trách nhiệm nuôi dưỡng, chăm sóc và giáo dục con chưa thành niên bất cứ lúc nào tùy thích.", "Kiểm tra nghĩa vụ của cha mẹ theo Luật Hôn nhân và Gia đình.", "Luật Hôn nhân và Gia đình Việt Nam năm 2014 (Điều 69).", "Sai", "Cha mẹ có nghĩa vụ thương yêu, chăm sóc, nuôi dưỡng, giáo dục và bảo vệ quyền, lợi ích hợp pháp của con chưa thành niên; việc trốn tránh nghĩa vụ nuôi dưỡng có thể bị xử lý theo pháp luật."),
    ("Luật An toàn thực phẩm và nguồn gốc xuất xứ", "AI nói các nhà hàng ăn uống được phép tự do sử dụng thực phẩm ôi thiu không rõ nguồn gốc xuất xứ để chế biến món ăn bán cho thực khách.", "Kiểm tra điều kiện bảo đảm an toàn thực phẩm trong kinh doanh dịch vụ ăn uống.", "Luật An toàn thực phẩm năm 2010 (Điều 30).", "Sai", "Cơ sở kinh doanh dịch vụ ăn uống bắt buộc phải có nguồn nước sạch, nguồn nguyên liệu thực phẩm có nguồn gốc xuất xứ rõ ràng và lưu mẫu thức ăn theo quy định để bảo đảm an toàn tính mạng cho người tiêu dùng."),
    ("Phòng cháy tại chung cư cao tầng", "AI khuyên khi xảy ra hỏa hoạn ở chung cư thì chạy ngay vào thang máy bấm nút xuống tầng 1 là cách thoát hiểm an toàn nhất.", "Kiểm tra hướng dẫn thoát hiểm chung cư khi có cháy.", "Cục Cảnh sát PCCC và Cứu nạn Cứu hộ.", "Sai", "Khi có hỏa hoạn hệ thống điện chung cư có thể bị ngắt đột ngột làm thang máy kẹt lơ lửng, hố thang máy trở thành ống khói hút khói độc gây ngạt tử vong; bắt buộc phải thoát hiểm bằng thang bộ có cửa chống cháy đóng kín."),
    ("Thủ tục công chứng hợp đồng mua bán nhà đất", "AI nói hợp đồng chuyển nhượng quyền sử dụng đất và tài sản gắn liền với đất giữa các cá nhân bắt buộc phải được công chứng hoặc chứng thực.", "Kiểm tra hình thức hợp đồng giao dịch bất động sản.", "Luật Đất đai năm 2024, Luật Nhà ở.", "Đúng", "Hợp đồng chuyển nhượng, tặng cho, thế chấp quyền sử dụng đất giữa các cá nhân bắt buộc phải được công chứng tại tổ chức hành nghề công chứng hoặc chứng thực tại UBND cấp xã mới có giá trị pháp lý."),
    ("Hành vi xả nước thải chưa qua xử lý ra sông", "AI nói các nhà máy công nghiệp được phép tự do xả trực tiếp nước thải chứa hóa chất độc hại chưa qua xử lý ra sông ngòi tự nhiên.", "Kiểm tra các hành vi bị nghiêm cấm trong Luật Bảo vệ Môi trường.", "Luật Bảo vệ Môi trường Việt Nam năm 2020 (Điều 6).", "Sai", "Luật Bảo vệ Môi trường nghiêm cấm hành vi xả nước thải chưa được xử lý đạt quy chuẩn kỹ thuật môi trường ra môi trường tự nhiên; vi phạm có thể bị phạt đình chỉ hoạt động hoặc xử lý hình sự về tội Gây ô nhiễm môi trường."),
    ("Thời hiệu xử phạt vi phạm hành chính", "AI nói thời hiệu xử phạt vi phạm hành chính trong hầu hết các lĩnh vực quản lý nhà nước thông thường là 1 năm.", "Kiểm tra thời hiệu xử phạt vi phạm hành chính.", "Luật Xử lý vi phạm hành chính năm 2012 (sửa đổi bổ sung 2020 - Điều 6).", "Đúng", "Thời hiệu xử phạt vi phạm hành chính thông thường là 01 năm; riêng một số lĩnh vực đặc thù như môi trường, thuế, sở hữu trí tuệ, xây dựng thời hiệu là 02 năm."),
    ("Biển báo cấm đi ngược chiều", "AI nói biển báo hình tròn nền đỏ có một vạch trắng nằm ngang ở giữa là biển báo cấm đi ngược chiều.", "Kiểm tra hệ thống biển báo hiệu giao thông đường bộ.", "Quy chuẩn QCVN 41:2019/BGTVT (Biển số P.102).", "Đúng", "Biển báo số P.102 (hình tròn nền đỏ, vạch ngang màu trắng) là biển 'Cấm đi ngược chiều', cấm tất cả các loại xe đi vào theo chiều đặt biển trừ các xe được ưu tiên theo quy định."),
    ("Người khuyết tật và quyền tiếp cận", "AI nói các công trình công cộng như tòa nhà, nhà ga, vỉa hè xây mới bắt buộc phải có thiết kế lối đi tiếp cận cho người khuyết tật.", "Kiểm tra quy định của Luật Người khuyết tật và Quy chuẩn xây dựng.", "Luật Người khuyết tật năm 2010 (Điều 40), Quy chuẩn QCVN 10:2014/BXD.", "Đúng", "Pháp luật quy định các công trình công cộng, chung cư và giao thông công cộng xây dựng mới bắt buộc phải tuân thủ quy chuẩn tiếp cận dành cho người khuyết tật (đường dốc, thang máy, lối vệ sinh chuyên dụng)."),
    ("Quyền khiếu nại tố cáo nặc danh", "AI nói đơn tố cáo gửi cơ quan nhà nước không ghi rõ họ tên địa chỉ người tố cáo thì cơ quan chức năng bắt buộc phải thụ lý giải quyết như đơn có tên.", "Kiểm tra quy định về xử lý đơn tố cáo không rõ họ tên người tố cáo.", "Luật Tố cáo Việt Nam năm 2018 (Điều 25).", "Sai", "Cơ quan nhà nước không thụ lý giải quyết đơn tố cáo không rõ họ tên, địa chỉ của người tố cáo; trừ trường hợp thông tin tố cáo kèm tài liệu, chứng cứ cụ thể về hành vi tham nhũng, lãng phí thì cơ quan có thẩm quyền tiến hành kiểm tra, thanh tra theo thẩm quyền."),
    ("Văn hóa nhường đường cho người đi bộ", "AI nói tại nơi có vạch kẻ đường dành cho người đi bộ, người lái xe phải quan sát, giảm tốc độ và nhường đường cho người đi bộ đang qua đường.", "Kiểm tra quy tắc nhường đường trong Luật Giao thông.", "Luật Giao thông đường bộ (Điều 11).", "Đúng", "Tại nơi có vạch kẻ đường dành cho người đi bộ, lái xe phải giảm tốc độ hoặc dừng lại nhường đường cho người đi bộ đang qua đường an toàn; hành vi không nhường đường bị xử phạt nghiêm khắc.")
]

print(f"Loaded {len(cybersecurity)} Cybersecurity and {len(law_society)} Law & Society scenarios.")
